425	```
426	
427	#### addcustom_operation.cpp
428	
429	File path: `src/kernels/kernels/addcustom/addcustom_operation.cpp`
430	Function: Selects the optimal kernel function.
431	
432	```c++
433	#include <mki/base/operation_base.h>
434	#include <mki_loader/op_register.h>
435	#include <mki/utils/log/log.h>
436	#include "asdops/params/params.h"
437	
438	namespace AsdOps {
439	using namespace Mki;
440	
441	static constexpr int32_t INPUT_NUM  = 2;
442	static constexpr int32_t OUTPUT_NUM = 1;
443	
444	class AddcustomOperation : public OperationBase {
445	public:
446	    explicit AddcustomOperation(const std::string &opName) noexcept : OperationBase(opName) {}
447	
448	    /* ---------- Kernel selection ---------- */
449	    Kernel *GetBestKernel(const LaunchParam &launchParam) const override
450	    {
451	        MKI_CHECK(IsConsistent(launchParam), "Fail to check consistent", return nullptr);
452	
453	        MKI_CHECK(launchParam.GetParam().Type() == typeid(OpParam::Addcustom),
454	                     "OpParam invalid", return nullptr);
455	
456	        auto dtype = launchParam.GetInTensor(0).desc.dtype;
457	        MKI_CHECK(dtype == TENSOR_DTYPE_INT32,
458	                     "Only int32 supported", return nullptr);
459	
460	        return GetKernelByName("AddcustomKernel");   // The kernel name must be the same as that registered.
461	    }
462	
463	    /* ---------- Tensor count ---------- */
464	    int64_t GetInputNum(const Any &specificParam) const override
465	    {
466	        (void)specificParam;
467	        return INPUT_NUM;
468	    }
469	
470	    int64_t GetOutputNum(const Any &specificParam) const override
471	    {
472	        (void)specificParam;
473	        return OUTPUT_NUM;
474	    }
475	
476	protected:
477	    /* ---------- Shape inference ---------- */
478	    Status InferShapeImpl(const LaunchParam &launchParam,
479	                          SVector<Tensor> &outTensors) const override
480	    {
481	        MKI_CHECK(launchParam.GetParam().Type() == typeid(OpParam::Addcustom),
482	                     "no match param type",
483	                     return Status::FailStatus(ERROR_INFERSHAPE_ERROR, "OpParam invalid"));
484	
485	        /* Output shape = Input shape */
486	        outTensors[0].desc = launchParam.GetInTensor(0).desc;
487	        return Status::OkStatus();
488	    }
489	};
490	
491	/* ---------- Registration ---------- */
492	REG_OPERATION(AddcustomOperation);
493	
494	}  // namespace AsdOps
495	```
496	
497	## ATB Framework Integration
498	
499	Compared with non-ATB operator development, after implementing the ATB operator, you need to develop interfaces to integrate the operator implementation into ATB. The integration process includes the development of `Runner` and `Operation`.
500	**Operation**: `Operation` is the user-facing front-end interface in the ATB for creating and managing operators. You can execute operators by creating an `Operation` object.
501	**Runner**: The execution unit of an `Operation`. It can be understood as the back-end processing logic of an `Operation`. A `Runner` is responsible for specifically executing the operator's computation tasks, including calling kernel functions, managing device memory, and processing tiling data.
502	
503	### Runner
504	
505	#### addcustom_ops_runner.h
506	
507	File path: `src/ops/ops_infer/addcustom/addcustom_ops_runner.h`
508	Function: The declaration header file for back-end processing logic functions
509	
510	```c++
511	#ifndef ATB_ADDCUSTOM_OPS_RUNNER_H
512	#define ATB_ADDCUSTOM_OPS_RUNNER_H
513	
514	#include "atb/infer_op_params.h"
515	#include "atb/runner/ops_runner.h"
516	
517	namespace atb {
518	
519	class AddcustomOpsRunner : public OpsRunner {
520	public:
521	    explicit AddcustomOpsRunner(const infer::AddcustomParam &param);
522	    ~AddcustomOpsRunner() override = default;
523	
524	protected:
525	    Status SetupKernelGraph(const OpsTensorPack &opsTensorPack) override;
526	    Status SetupKernelGraphAddInt32();
527	private:
528	    infer::AddcustomParam param_;
529	};
530	
531	}  // namespace atb
532	#endif  // ATB_ADDCUSTOM_OPS_RUNNER_H
533	```
534	
535	#### addcustom_ops_runner.cpp
536	
537	File path: `src/ops/ops_infer/addcustom/addcustom_ops_runner.cpp`
538	Function: Backend processing logic
539	
540	```c++
541	#include "addcustom_ops_runner.h"
542	#include <asdops/params/params.h>
543	#include <atb/utils/log.h>
544	#include "atb/utils/operation_register.h"
545	#include "atb/utils/param_compare.h"
546	
547	namespace atb {
548	
549	AddcustomOpsRunner::AddcustomOpsRunner(const infer::AddcustomParam &param)
550	    : OpsRunner("AddcustomOpsRunner"), param_(param)
551	{
552	    ATB_LOG(INFO) << "AddcustomOpsRunner::AddcustomOpsRunner";
553	}
554	
555	/* ---------- Framework callback ---------- */
556	Status AddcustomOpsRunner::SetupKernelGraph(const OpsTensorPack &opsTensorPack)
557	{
558	    (void)opsTensorPack;   // No additional validation required.
559	
560	    const size_t inTensorNum  = 2;
561	    const size_t outTensorNum = 1;
562	    const size_t nodeNum      = 1;
563	
564	    kernelGraph_.inTensors.resize(inTensorNum);
565	    kernelGraph_.outTensors.resize(outTensorNum);
566	    kernelGraph_.internalTensors.clear();
567	    kernelGraph_.nodes.resize(nodeNum);
568	
569	    return SetupKernelGraphAddInt32();
570	}
571	
572	/* ---------- Computation graph creation ---------- */
573	Status AddcustomOpsRunner::SetupKernelGraphAddInt32()
574	{
575	    ATB_LOG(INFO) << GetLogPrefix() << "AddcustomOpsRunner::SetupKernelGraphAddInt32";
576	
577	    /* Input 0: x; input 1: y */
578	    Mki::Tensor &xTensor = kernelGraph_.inTensors[0];
579	    Mki::Tensor &yTensor = kernelGraph_.inTensors[1];
580	
581	    /* Output 0: z = x + y */
582	    Mki::Tensor &zTensor = kernelGraph_.outTensors[0];
583	
584	    /* Single Addcustom compute node */
585	    KernelGraphNode &addNode = kernelGraph_.nodes[0];
586	
587	    AsdOps::OpParam::Addcustom addParam{param_.addcustomDim}; // If not required, set it to 0.
588	    addNode.opDesc    = {0, "AddcustomOperation", addParam};
589	    addNode.inTensors = {&xTensor, &yTensor};
590	    addNode.outTensors = {&zTensor};
591	
592	    return NO_ERROR;
593	}
594	
595	// Register the current runner: AddCustomOpsRunner, which must be the same as the current runner name. Ensure that the runner name is unique to avoid duplicate registration.
596	REG_RUNNER_TYPE(AddcustomOpsRunner);
597	// Register the new operator parameter AsdOps::OpParam::Addcustom used in the current runner. Ensure that the operator parameter is unique to avoid duplicate registration.
598	REG_OP_PARAM(AsdOps::OpParam::Addcustom);
599	}  // namespace atb
600	```
601	
602	### Operation
603	
604	#### addcustom_operation.h
605	
606	File path: `src/ops/ops_infer/addcustom/addcustom_operation.h`
607	Function: The declaration header file for creating and managing operator functions
608	
609	```c++
610	#ifndef ATB_Addcustom_OPERATION_H
611	#define ATB_Addcustom_OPERATION_H
612	
613	#include "atb/infer_op_params.h"
614	#include "atb/operation/operation_base.h"
615	
616	namespace atb {
617	
618	class AddcustomOperation : public OperationBase {
