626	protected:
627	    Status InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
628	                          SVector<TensorDesc> &outTensorDescs) const override;
629	    Status InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const override;
630	    Status SetupCheckImpl(const SVector<Tensor> &inTensors,
631	                          const SVector<Tensor> &outTensors) const override;
632	    std::shared_ptr<Runner> CreateRunner(Context &context) const override;
633	    nlohmann::json GetParamJson() const override;
634	
