645	
646	#### addcustom_operation.cpp
647	
648	File path: `src/ops/ops_infer/addcustom/addcustom_operation.cpp`
649	Function: The file for creating and managing operator functions
650	
651	```c++
652	#include "addcustom_operation.h"
653	
654	#include "addcustom_ops_runner.h"
655	#include "atb/operation/atb_operation_ir_cfg.h"
656	#include "atb/operation/op_param_funcs.h"
657	#include "atb/utils/operation_util.h"
658	#include "atb/utils/param_to_json.h"
659	#include "atb/utils/singleton.h"
660	#include "atb/utils/tensor_check.h"
661	
662	namespace atb {
663	
664	/* ---------- Factory function ---------- */
665	template <>
666	Status CreateOperation(const infer::AddcustomParam &opParam, Operation **operation)
667	{
668	    if (operation == nullptr) return ERROR_INVALID_PARAM;
669	    OP_PARAM_RSV_CHECK(opParam);
670	
671	    *operation = new (std::nothrow) AddcustomOperation(opParam);
672	    if (*operation == nullptr) {
673	        ATB_LOG(ERROR) << "failed to new AddcustomOperation";
674	        return ERROR_INTERNAL_ERROR;
675	    }
676	    return NO_ERROR;
677	}
678	
679	/* ---------- Construction/Destruction ---------- */
680	AddcustomOperation::AddcustomOperation(const infer::AddcustomParam &param)
681	    : OperationBase("AddcustomOperation"), param_(param)
682	{
683	    operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr("AddcustomOperation");
684	}
685	
686	/* ---------- Number of inputs/outputs ---------- */
687	uint32_t AddcustomOperation::GetInputNum() const { return 2; }
688	uint32_t AddcustomOperation::GetOutputNum() const { return 1; }
689	
690	/* ---------- Shape inference ---------- */
691	Status AddcustomOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
692	                                          SVector<TensorDesc> &outTensorDescs) const
693	{
694	    outTensorDescs[0] = inTensorDescs[0]; // The output is identical to input 0.
695	    return NO_ERROR;
696	}
697	
698	/* ---------- Validation ---------- */
699	Status AddcustomOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
700	{
701	    return InTensorDescsCheck(inTensorDescs);
702	}
703	
704	Status AddcustomOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
705	{
706	    SVector<TensorDesc> inTensorDescs;
707	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
708	    ATB_LOG(DEBUG) << "outTensors size:" << outTensors.size();
709	
710	    return InTensorDescsCheck(inTensorDescs);
711	}
712	
713	/* ---------- Runner creation ---------- */
714	std::shared_ptr<Runner> AddcustomOperation::CreateRunner(Context &context) const
715	{
716	    (void)context;
717	    return std::make_shared<AddcustomOpsRunner>(param_);
718	}
719	
720	/* ---------- Parameter JSON ---------- */
721	nlohmann::json AddcustomOperation::GetParamJson() const { return OpParamToJson(param_); }
722	
723	/* ---------- Specific validation ---------- */
724	Status AddcustomOperation::InTensorDescsCheck(const SVector<TensorDesc> &inTensorDescs) const
725	{
726	    // Count
727	    if (inTensorDescs.size() != 2) {
728	        ATB_LOG(ERROR) << GetLogPrefix() << "Addcustom expect 2 inputs";
729	        return ERROR_INVALID_PARAM;
730	    }
731	
732	    // shape
733	    if (inTensorDescs[0].shape.dimNum != inTensorDescs[1].shape.dimNum) {
734	        ATB_LOG(ERROR) << GetLogPrefix() << "Addcustom inputs must have same shape";
735	        return ERROR_INVALID_PARAM;
736	    }
737	    return NO_ERROR;
738	}
739	
740	}  // namespace atb
