788	
789	#### addcustom_demo.cpp
790	
791	File path: `example/op_demo/addcustom/addcustom_demo.cpp`
792	Function: Creates and calls `AddcustomOperation`.
793	
794	```c++
795	#include "../demo_util.h"
796	
797	const int32_t DEVICE_ID = 0;
798	const uint32_t DIM_0 = 8;
799	const uint32_t DIM_1 = 512;
800	
801	/**
802	 * @brief Prepare the input tensors for Addcustom (both inputs have the same shape).
803	 */
804	atb::Status PrepareInTensor(atb::Context *contextPtr, aclrtStream stream, atb::SVector<atb::Tensor> &inTensors)
805	{
806	    // Input x: [8, 512], int32, all ones
807	    atb::Tensor x;
808	    CHECK_STATUS(CreateTensorFromVector(contextPtr, stream, std::vector<int32_t>(DIM_0 * DIM_1, 1), ACL_INT32,
809	                                        aclFormat::ACL_FORMAT_ND, {DIM_0, DIM_1}, x));
810	
811	    // Input y: [8, 512], int32, all twos
812	    atb::Tensor y;
813	    CHECK_STATUS(CreateTensorFromVector(contextPtr, stream, std::vector<int32_t>(DIM_0 * DIM_1, 2), ACL_INT32,
814	                                        aclFormat::ACL_FORMAT_ND, {DIM_0, DIM_1}, y));
815	
816	    inTensors = {x, y};
817	    return atb::ErrorType::NO_ERROR;
818	}
819	
820	/**
821	 * @brief Create an AddcustomOperation.
822	 */
823	atb::Status CreateAddcustomOperation(atb::Operation **addOp)
824	{
825	    atb::infer::AddcustomParam param;
826	    param.addcustomDim = 0;
827	    CHECK_STATUS(atb::CreateOperation(param, addOp));
828	    return atb::ErrorType::NO_ERROR;
829	}
830	
831	int main(int argc, char **argv)
832	{
833	    CHECK_STATUS(aclInit(nullptr));
834	    int32_t deviceId = 0;
835	    CHECK_STATUS(aclrtSetDevice(deviceId));
836	
837	    atb::Context *context = nullptr;
838	    CHECK_STATUS(atb::CreateContext(&context));
839	    void *stream = nullptr;
840	    CHECK_STATUS(aclrtCreateStream(&stream));
841	    context->SetExecuteStream(stream);
842	
843	    /* OP creation */
844	    atb::Operation *addOp = nullptr;
845	    CHECK_STATUS(CreateAddcustomOperation(&addOp));
846	
847	    /* Input/output preparation */
848	    atb::VariantPack variantPack;
849	    CHECK_STATUS(PrepareInTensor(context, stream, variantPack.inTensors));
850	
851	    atb::Tensor output;
852	    CHECK_STATUS(CreateTensorFromVector(context, stream, std::vector<int32_t>(DIM_0 * DIM_1, 0),  // Placeholder
853	                                        ACL_INT32, aclFormat::ACL_FORMAT_ND, {DIM_0, DIM_1}, output));
854	    variantPack.outTensors = {output};
855	
856	    /* Setup -> Execute */
857	    uint64_t workspaceSize = 0;
858	    CHECK_STATUS(addOp->Setup(variantPack, workspaceSize, context));
859	    uint8_t *workspacePtr = nullptr;
860	    if (workspaceSize > 0) {
861	        CHECK_STATUS(aclrtMalloc((void **)&workspacePtr, workspaceSize, ACL_MEM_MALLOC_HUGE_FIRST));
862	    }
863	    CHECK_STATUS(addOp->Execute(variantPack, workspacePtr, workspaceSize, context));
864	    CHECK_STATUS(aclrtSynchronizeStream(stream));
865	
866	    /* Resource release */
867	    for (auto &t : variantPack.inTensors) aclrtFree(t.deviceData);
868	    for (auto &t : variantPack.outTensors) aclrtFree(t.deviceData);
869	    if (workspacePtr) {
870	        aclrtFree(workspacePtr);
871	    }
872	    atb::DestroyOperation(addOp);
873	    aclrtDestroyStream(stream);
874	    DestroyContext(context);
875	    aclFinalize();
876	    std::cout << "Addcustom demo success!" << std::endl;
877	    return 0;
878	}
